            r"\n;&|()\x60\x22\x27][^ \t\n;&|()\x60\x22\x27]*)|[^ \t\n;&|()\x60\x22\x27"
            r"\x72][^ \t\n;&|()\x60\x22\x27]*)?|[^ \t\n;&|()\x60\x22\x27\x65][^ \t\n;&|"
            r"()\x60\x22\x27]*)?|[^ \t\n;&|()\x60\x22\x27\x69\x6e\x73][^ \t\n;&|()\x60"
            r"\x22\x27]*)?|[^ \t\n;&|()\x60\x22\x27\x61\x62\x63\x64\x67\x6c\x6d\x6e\x70"
            r"\x73\x75][^ \t\n;&|()\x60\x22\x27]*)|-[^ \t\n;&|()\x60\x22\x27\x2d\x44"
            r"\x67\x75]+|-[^ \t\n;&|()\x60\x22\x27\x2d\x44\x67\x75]*[\x44\x67\x75](?:[ "
            r"\t]+(?:\x22[^\x22\n]*\x22|\x27[^\x27\n]*\x27|[^ \t\n;&|()\x60\x22\x27]+)|"
            r"[^ \t\n;&|()\x60\x22\x27]+)))*[ \t]+(?:(?:(?:[^ \t\n;&|()\x60\x22\x27]*/)"
            r"?(?:(?:ba|da|k|z)?sh)[ \t]+-[A-Za-z]*c[A-Za-z]*[ \t]+|eval[ \t]+)(?:\\?["
            r"\x22\x27])*)*(?:\\?[\x22\x27])?(?:(?:\\?[\x22\x27])?(?:[^ \t\n;&|()\x60"
            r"\x22\x27]*/)?(?:\\?p\\?r\\?a\\?e\\?t\\?o\\?r\\?c\\?t\\?l)(?:\\?[\x22\x27]"
            r")?|(?:\\?[\x22\x27])?(?:[^ \t\n;&|()\x60\x22\x27]*/)?(?:\\?s\\?t\\?a\\?n"
            r"\\?d\\?a\\?r\\?d\\?s\\?c\\?t\\?l)(?:\\?[\x22\x27])?)[ \t]+(?:adopt|"
            r"conform|bootstrap|needs[ \t]+(?:scan|report|migrate|epic))[ \t]+(?:(?:"
            r"\x22[^\x22\n]*\x22|\x27[^\x27\n]*\x27|[^ \t\n;&|()\x60\x22\x27]+)[ \t]+)*"
            r"(?:(?:[^ \t\n;&|()\x60\x22\x27]*[/\\])?dev[/\\]?|\x22(?:[^\x22\n]*[/\\])?"
            r"dev[/\\]?\x22|\x27(?:[^\x27\n]*[/\\])?dev[/\\]?\x27)(?:[ \t\r\n;&|(){}"
            r"\x22\x27]|$)|(?:\\?[\x22\x27])?(?:[^ \t\n;&|()\x60\x22\x27]*/)?(?:\\?s\\?"
            r"u)(?:\\?[\x22\x27])?(?:[ \t]+(?:\x22[^\x22\n]*\x22|\x27[^\x27\n]*\x27|[^ "
            r"\t\n;&|()\x60\x22\x27]+))*[ \t]+(?:-[A-Za-z]*c[A-Za-z]*[ \t]*|--command(?"
            r":=|[ \t]+))(?:(?:(?:[^ \t\n;&|()\x60\x22\x27]*/)?(?:(?:ba|da|k|z)?sh)[ \t"
            r"]+-[A-Za-z]*c[A-Za-z]*[ \t]+|eval[ \t]+)(?:\\?[\x22\x27])*)*(?:\\?[\x22"
            r"\x27])?(?:(?:\\?[\x22\x27])?(?:[^ \t\n;&|()\x60\x22\x27]*/)?(?:\\?p\\?r\\"
            r"?a\\?e\\?t\\?o\\?r\\?c\\?t\\?l)(?:\\?[\x22\x27])?|(?:\\?[\x22\x27])?(?:[^"
            r" \t\n;&|()\x60\x22\x27]*/)?(?:\\?s\\?t\\?a\\?n\\?d\\?a\\?r\\?d\\?s\\?c\\?"
            r"t\\?l)(?:\\?[\x22\x27])?)[ \t]+(?:adopt|conform|bootstrap|needs[ \t]+(?:"
            r"scan|report|migrate|epic))[ \t]+(?:(?:\x22[^\x22\n]*\x22|\x27[^\x27\n]*"
            r"\x27|[^ \t\n;&|()\x60\x22\x27]+)[ \t]+)*(?:(?:[^ \t\n;&|()\x60\x22\x27]*["
            r"/\\])?dev[/\\]?|\x22(?:[^\x22\n]*[/\\])?dev[/\\]?\x22|\x27(?:[^\x27\n]*[/"
            r"\\])?dev[/\\]?\x27)(?:[ \t\r\n;&|(){}\x22\x27]|$))"
